import { readFile, readdir, writeFile } from 'node:fs/promises';
const directory = new URL('../supabase/migrations/', import.meta.url);
const files = (await readdir(directory)).filter(file => file.endsWith('.sql')).sort();
const sections = await Promise.all(files.map(async file => {
  const sql = await readFile(new URL(file, directory), 'utf8');
  return `-- ${file}\n${sql.replace(/^begin;\s*/, '').replace(/\s*commit;\s*$/, '')}`;
}));
await writeFile(new URL('../supabase/setup.sql', import.meta.url),
  '-- Generated by node scripts/prepare-supabase.mjs.\n-- Initial Claro setup only: apply ONCE to a project where these migrations are not yet deployed.\n-- All migrations run in one transaction. No credentials are included.\nbegin;\n\n' + sections.join('\n\n') + '\n\ncommit;\n');
console.log(`Prepared supabase/setup.sql from ${files.length} migrations.`);
